#include <zephyr/drivers/dac.h>
#include <zephyr/drivers/emul/dac_emul.h> 
#include <zephyr/kernel.h>
#include <zephyr/ztest.h>

#define DAC_EMULS_NODE DT_NODELABEL(dac_emuls)

static const struct device *const dac_emul_devs[] = {
	DEVICE_DT_GET_BY_IDX(DAC_EMULS_NODE, 0),
	DEVICE_DT_GET_BY_IDX(DAC_EMULS_NODE, 1),
	DEVICE_DT_GET_BY_IDX(DAC_EMULS_NODE, 2),
};

struct dac_emul_test_fixture {
	const struct device *dev;
};

static void *dac_emul_setup(void)
{
	static struct dac_emul_test_fixture fixture;

	zassert_true(device_is_ready(dac_emul_devs[0]));
	zassert_true(device_is_ready(dac_emul_devs[1]));
	zassert_true(device_is_ready(dac_emul_devs[2]));

	fixture.dev = dac_emul_devs[0];

	return &fixture;
}

ZTEST_F(dac_emul_tests, test_write_unconfigured_channel)
{
	const struct dac_channel_cfg cfg = {
		.channel_id = 0,
		.resolution = 12,
	};

	zassert_ok(dac_write_value(fixture->dev, cfg.channel_id, 1234));
}

ZTEST_F(dac_emul_tests, test_read_value_unconfigured_channel)
{
	uint16_t val;

	/* Reading from an unconfigured channel should fail */
	zassert_not_ok(dac_read_value(dac_emul_devs[1], 0, &val));
}

ZTEST_F(dac_emul_tests, test_channel_cfg)
{
	const struct dac_channel_cfg cfg = {
		.channel_id = 0,
		.resolution = 12,
	};

	zassert_ok(dac_channel_setup(fixture->dev, &cfg));
}

ZTEST_F(dac_emul_tests, test_multiple_devices_independent)
{
	const struct dac_channel_cfg cfg0 = {
		.channel_id = 0,
		.resolution = 12,
	};
	const struct dac_channel_cfg cfg1 = {
		.channel_id = 0,
		.resolution = 8,
	};

	zassert_ok(dac_channel_setup(dac_emul_devs[0], &cfg0));
	zassert_ok(dac_channel_setup(dac_emul_devs[1], &cfg1));

	zassert_ok(dac_write_value(dac_emul_devs[0], 0, 0xaaa));
	zassert_ok(dac_write_value(dac_emul_devs[1], 0, 0xbb));

	uint32_t raw_val;

	zassert_ok(dac_emul_value_get(dac_emul_devs[0], &raw_val));
	zassert_equal(raw_val, 0xaaa);

	zassert_ok(dac_emul_value_get(dac_emul_devs[1], &raw_val));
	zassert_equal(raw_val, 0xbb);
}

ZTEST_F(dac_emul_tests, test_write_value)
{
	const struct dac_channel_cfg cfg = {
		.channel_id = 0,
		.resolution = 12,
	};

	zassert_ok(dac_channel_setup(fixture->dev, &cfg));

	/* Value is within the 12-bit resolution */
	zassert_ok(dac_write_value(fixture->dev, 0, 0xfff));

	/* Value is larger than the 12-bit resolution */
	zassert_not_ok(dac_write_value(fixture->dev, 0, 0x1000));
}

ZTEST_F(dac_emul_tests, test_1bit_resolution)
{
	const struct device *dev = dac_emul_devs[2];
	const struct dac_channel_cfg cfg = {
		.channel_id = 0,
		.resolution = 1,
	};
	uint32_t raw_val;

	zassert_ok(dac_channel_setup(dev, &cfg));

	zassert_ok(dac_write_value(dev, 0, 0));
	zassert_ok(dac_emul_value_get(dev, &raw_val));
	zassert_equal(raw_val, 0);

	zassert_ok(dac_write_value(dev, 0, 1));
	zassert_ok(dac_emul_value_get(dev, &raw_val));
	zassert_equal(raw_val, 1);

	/* Value is larger than the 1-bit resolution */
	zassert_not_ok(dac_write_value(dev, 0, 2));
}

ZTEST_SUITE(dac_emul_tests, NULL, dac_emul_setup, NULL, NULL, NULL);
